#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_TENANT_ID 64
#define MAX_DB_NAME 128
#define MAX_PATH 4096
#define DATA_ROOT "/var/lib/mtdb/data"

typedef struct {
    char tenant_id[MAX_TENANT_ID];
    char db_name[MAX_DB_NAME];
    int  isolation_level;
    char resolved_path[MAX_PATH];
} db_context_t;

typedef struct {
    char segment[256];
    int  depth;
} path_segment_t;

/* Normalize a single path segment: strip leading/trailing whitespace */
static int normalize_segment(const char *input, char *output, size_t outlen) {
    const char *start = input;
    const char *end;
    size_t len;

    while (*start == ' ' || *start == '\t') start++;
    end = start + strlen(start) - 1;
    while (end > start && (*end == ' ' || *end == '\t')) end--;
    len = (size_t)(end - start + 1);
    if (len >= outlen) return -1;
    memcpy(output, start, len);
    output[len] = '\0';
    return 0;
}

/* Validate tenant ID: alphanumeric and hyphens only */
static int validate_tenant_id(const char *tid) {
    if (!tid || strlen(tid) == 0 || strlen(tid) >= MAX_TENANT_ID)
        return -1;
    for (const char *p = tid; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '-'))
            return -1;
    }
    return 0;
}

/* Validate db_name: only allow alphanumeric, hyphens, underscores */
static int validate_db_name(const char *name) {
    if (!name || strlen(name) == 0 || strlen(name) >= MAX_DB_NAME)
        return -1;
    for (const char *p = name; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '-' || *p == '_'))
            return -1;
    }
    return 0;
}

/* Resolve the database path with tenant isolation enforcement */
static int resolve_db_path(db_context_t *ctx) {
    char candidate[MAX_PATH];
    char normalized_db[MAX_DB_NAME];
    char real_candidate[PATH_MAX];
    char real_root[PATH_MAX];

    if (normalize_segment(ctx->db_name, normalized_db, MAX_DB_NAME) != 0)
        return -1;

    /* Strict allowlist validation - no path separators or dots allowed */
    if (validate_db_name(normalized_db) != 0)
        return -1;

    /* Build candidate path */
    int written = snprintf(candidate, MAX_PATH, "%s/%s/%s.db",
                           DATA_ROOT, ctx->tenant_id, normalized_db);
    if (written < 0 || written >= MAX_PATH)
        return -1;

    /* Resolve symlinks and canonicalize the data root */
    if (realpath(DATA_ROOT, real_root) == NULL)
        return -1;

    /* Build and verify tenant root using O_NOFOLLOW to prevent symlink attacks */
    char tenant_root[MAX_PATH];
    snprintf(tenant_root, MAX_PATH, "%s/%s", real_root, ctx->tenant_id);

    /* Create tenant directory if needed - use open with O_NOFOLLOW */
    int dir_fd = open(real_root, O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
    if (dir_fd < 0) return -1;
    mkdirat(dir_fd, ctx->tenant_id, 0750);
    close(dir_fd);

    /* Verify tenant_root resolves correctly and is a directory */
    char real_tenant[PATH_MAX];
    if (realpath(tenant_root, real_tenant) == NULL)
        return -1;

    /* Ensure tenant root is directly under data root */
    size_t root_len = strlen(real_root);
    if (strncmp(real_tenant, real_root, root_len) != 0 ||
        real_tenant[root_len] != '/')
        return -1;
    /* Ensure no additional path separators (no subdirectory escape) */
    if (strchr(real_tenant + root_len + 1, '/') != NULL)
        return -1;

    struct stat st;
    if (lstat(real_tenant, &st) != 0 || !S_ISDIR(st.st_mode))
        return -1;
    /* Reject if tenant root is a symlink */
    if (S_ISLNK(st.st_mode))
        return -1;

    /* Now resolve the full candidate path */
    if (realpath(candidate, real_candidate) == NULL) {
        /* File doesn't exist yet - since db_name is strictly validated
         * (no slashes, no dots, no special chars), the file will be
         * directly in tenant_root. Verify by construction. */
        snprintf(ctx->resolved_path, MAX_PATH, "%s/%s.db",
                 real_tenant, normalized_db);
    } else {
        /* File exists - verify it's directly within tenant root */
        size_t tenant_len = strlen(real_tenant);
        if (strncmp(real_candidate, real_tenant, tenant_len) != 0 ||
            real_candidate[tenant_len] != '/')
            return -1;
        /* Ensure no further directory traversal */
        if (strchr(real_candidate + tenant_len + 1, '/') != NULL)
            return -1;
        /* Ensure destination is always null-terminated */
        strncpy(ctx->resolved_path, real_candidate, MAX_PATH - 1);
        ctx->resolved_path[MAX_PATH - 1] = '\0';
    }

    return 0;
}

/* Public API: open a database for a given tenant */
int mtdb_open(const char *tenant_id, const char *db_name, int flags) {
    db_context_t ctx;
    memset(&ctx, 0, sizeof(ctx));

    if (validate_tenant_id(tenant_id) != 0) {
        fprintf(stderr, "Invalid tenant ID\n");
        return -1;
    }

    /* Guard against NULL/overlong db_name before using it */
    if (db_name == NULL || strlen(db_name) == 0 || strlen(db_name) >= MAX_DB_NAME) {
        fprintf(stderr, "Invalid db name\n");
        return -1;
    }

    strncpy(ctx.tenant_id, tenant_id, MAX_TENANT_ID - 1);
    strncpy(ctx.db_name, db_name, MAX_DB_NAME - 1);
    ctx.isolation_level = flags;

    if (resolve_db_path(&ctx) != 0) {
        fprintf(stderr, "Path resolution failed for tenant %s\n", tenant_id);
        return -1;
    }

    printf("Opening database: %s\n", ctx.resolved_path);
    /* In production: return fd from open(ctx.resolved_path, O_NOFOLLOW, ...) */
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <tenant_id> <db_name>\n", argv[0]);
        return 1;
    }
    return mtdb_open(argv[1], argv[2], 0);
}
